import{_ as h,o as t,c as i,a2 as c}from"./chunks/framework.mRCPFc5l.js";const l=JSON.parse('{"title":"Sinh học","description":"","frontmatter":{},"headers":[],"relativePath":"ideas/inquiry-ib/sinh-hoc.md","filePath":"ideas/inquiry-ib/sinh-hoc.md"}'),o={name:"ideas/inquiry-ib/sinh-hoc.md"};function g(a,n,u,e,r,m){return t(),i("div",null,[...n[0]||(n[0]=[c('<h1 id="sinh-hoc" tabindex="-1">Sinh học <a class="header-anchor" href="#sinh-hoc" aria-label="Permalink to &quot;Sinh học&quot;">​</a></h1><p>Trên trang này# Sinh học — ba bài học inquiry theo IB <a href="#sinh-hoc-—-ba-bai-hoc-inquiry-theo-ib">​</a> Sinh học dễ trượt thành môn học thuộc: nhiều tên gọi, nhiều sơ đồ, nhiều quá trình phải nhớ. Inquiry kéo môn này về đúng bản chất của nó. Ý xuyên suốt cả mônSinh học là môn về cơ chế: cái gì gây ra cái gì, và làm sao ta biết. Không có &quot;để mà&quot;, không có ý muốn — chỉ có điều kiện dẫn tới kết quả. Cũng quan trọng — nhưng không phải ý lớn nhất- Sinh vật không thay đổi để thích nghi. Cái thay đổi là tỷ lệ các cá thể trong quần thể.</p><ul><li>Hệ sống giữ được cân bằng bằng những dòng chảy không cần ai điều khiển.</li><li>Nhiều đại lượng không nhìn thấy được vẫn suy ra được từ những phép đo gián tiếp.</li></ul><h2 id="demo-1-—-tham-thau-vi-sao-rau-heo-lai-tuoi-lai-khi-ngam-nuoc-​" tabindex="-1">Demo 1 — Thẩm thấu: vì sao rau héo lại tươi lại khi ngâm nước? <a href="#demo-1-—-tham-thau-vi-sao-rau-heo-lai-tuoi-lai-khi-ngam-nuoc">​</a> <a class="header-anchor" href="#demo-1-—-tham-thau-vi-sao-rau-heo-lai-tuoi-lai-khi-ngam-nuoc-​" aria-label="Permalink to &quot;Demo 1 — Thẩm thấu: vì sao rau héo lại tươi lại khi ngâm nước? [​](#demo-1-—-tham-thau-vi-sao-rau-heo-lai-tuoi-lai-khi-ngam-nuoc)&quot;">​</a></h2><p><strong>Lớp</strong>8–10<strong>Key concept</strong>Systems<strong>Related concepts</strong>Balance · Movement · Models<strong>Global context</strong>Identities and relationships<strong>Statement of inquiry</strong>Các hệ sống duy trì cân bằng bằng những dòng chảy diễn ra không cần điều khiển có ý thức.<strong>Cần biết trước</strong>Tế bào, màng tế bào, khái niệm dung dịch</p><h3 id="ba-cau-hoi-​" tabindex="-1">Ba câu hỏi <a href="#ba-cau-hoi">​</a> <a class="header-anchor" href="#ba-cau-hoi-​" aria-label="Permalink to &quot;Ba câu hỏi [​](#ba-cau-hoi)&quot;">​</a></h3><ul><li><strong>Factual:</strong> Thẩm thấu là gì? Khuếch tán là gì?</li><li><strong>Conceptual:</strong> Vì sao nước di chuyển mà không cần năng lượng nào đẩy nó?</li><li><strong>Debatable:</strong> Ướp muối để bảo quản thực phẩm có phải một cách &quot;tự nhiên&quot; không?</li></ul><h3 id="dien-bien-tiet-hoc-​" tabindex="-1">Diễn biến tiết học <a href="#dien-bien-tiet-hoc">​</a> <a class="header-anchor" href="#dien-bien-tiet-hoc-​" aria-label="Permalink to &quot;Diễn biến tiết học [​](#dien-bien-tiet-hoc)&quot;">​</a></h3><p><strong>Bước 1 — Hiện tượng bếp núc (5 phút).</strong> Giáo viên đưa hai đĩa: một đĩa rau đã héo, một đĩa cùng loại rau đã ngâm nước 30 phút và giờ giòn trở lại. <em>&quot;Chuyện gì đã xảy ra? Nước đi vào bằng cách nào — rau có miệng đâu?&quot;</em><strong>Bước 2 — Thí nghiệm khoai tây (20 phút).</strong> Mỗi nhóm cắt sáu thanh khoai tây bằng nhau, cân từng thanh, rồi ngâm vào sáu cốc nước muối nồng độ khác nhau: 0% · 2% · 5% · 10% · 15% · 20%. Sau 30 phút: cân lại, ghi phần trăm thay đổi khối lượng. Trong lúc chờ, học sinh <strong>dự đoán</strong> và vẽ đồ thị dự đoán của mình. Bước dự đoán này quan trọng — nó biến việc chờ thành việc suy nghĩ, và làm kết quả trở nên đáng nhớ dù nó khớp hay không khớp. <strong>Bước 3 — Đối chiếu (10 phút).</strong> Kết quả điển hình: thanh trong nước tinh khiết nặng lên ~8%; thanh trong nước muối 20% nhẹ đi ~12%; ở đâu đó khoảng 5–7% thì khối lượng gần như không đổi. <em>&quot;Điểm mà khối lượng không đổi có nghĩa gì?&quot;</em> Học sinh dần đi tới: đó là lúc nồng độ trong và ngoài bằng nhau. <strong>Và điều đó có nghĩa là các em vừa đo được nồng độ bên trong tế bào khoai tây</strong> — bằng một thí nghiệm mà không ai nhìn thấy tế bào nào. Khoảnh khắc này thường gây ấn tượng mạnh: một đại lượng không quan sát trực tiếp được lại suy ra được từ những phép đo gián tiếp. <strong>Bước 4 — Xây mô hình (12 phút).</strong><em>&quot;Vẽ cho tôi thấy chuyện gì xảy ra ở mức phân tử.&quot;</em> Học sinh vẽ. Giáo viên hỏi những câu đẩy sâu:</p><ul><li><em>&quot;Nước đi một chiều hay hai chiều?&quot;</em> (Đây là hiểu lầm phổ biến nhất — nước đi cả hai chiều, chỉ là không cân bằng.)</li><li><em>&quot;Cái gì đẩy nước đi? Có ai bơm không?&quot;</em></li><li><em>&quot;Vì sao muối không đi ngược ra ngoài để cân bằng?&quot;</em> Câu cuối dẫn tới khái niệm màng bán thấm — và học sinh cần nó vì mô hình của chính các em đang thiếu. <strong>Bước 5 — Nối ra đời sống (10 phút).</strong><em>&quot;Vì sao ướp muối bảo quản được cá? Vì sao truyền dịch phải đúng nồng độ? Vì sao uống nước biển lại càng khát?&quot;</em> Câu cuối luôn tạo tranh luận sôi nổi, và học sinh giải thích được nó bằng chính mô hình vừa dựng.</li></ul><h3 id="cham-theo-tieu-chi-​" tabindex="-1">Chấm theo tiêu chí <a href="#cham-theo-tieu-chi">​</a> <a class="header-anchor" href="#cham-theo-tieu-chi-​" aria-label="Permalink to &quot;Chấm theo tiêu chí [​](#cham-theo-tieu-chi)&quot;">​</a></h3><p>Tiêu chíỞ bài này<strong>A</strong>Định nghĩa và phân biệt khuếch tán, thẩm thấu<strong>B</strong>Thiết kế thí nghiệm khoai tây, xác định biến kiểm soát<strong>C</strong>Vẽ đồ thị, xác định điểm cân bằng, đánh giá sai số<strong>D</strong>Bàn về ứng dụng: bảo quản thực phẩm, y tế, nông nghiệp</p><h2 id="demo-2-—-quang-hop-chung-minh-cay-an-khong-khi-​" tabindex="-1">Demo 2 — Quang hợp: chứng minh cây &quot;ăn&quot; không khí <a href="#demo-2-—-quang-hop-chung-minh-cay-an-khong-khi">​</a> <a class="header-anchor" href="#demo-2-—-quang-hop-chung-minh-cay-an-khong-khi-​" aria-label="Permalink to &quot;Demo 2 — Quang hợp: chứng minh cây &quot;ăn&quot; không khí [​](#demo-2-—-quang-hop-chung-minh-cay-an-khong-khi)&quot;">​</a></h2><p><strong>Lớp</strong>9–11<strong>Key concept</strong>Change<strong>Related concepts</strong>Transformation · Energy · Evidence<strong>Global context</strong>Globalization and sustainability<strong>Statement of inquiry</strong>Vật chất chuyển từ dạng này sang dạng khác qua các quá trình sống, và bằng chứng cho những chuyển đổi đó phải được thiết kế để thu thập.<strong>Cần biết trước</strong>Tế bào thực vật, khái niệm khí CO₂ và O₂</p><h3 id="dien-bien-tiet-hoc-​-1" tabindex="-1">Diễn biến tiết học <a href="#dien-bien-tiet-hoc-1">​</a> <a class="header-anchor" href="#dien-bien-tiet-hoc-​-1" aria-label="Permalink to &quot;Diễn biến tiết học [​](#dien-bien-tiet-hoc-1)&quot;">​</a></h3><p><strong>Bước 1 — Câu hỏi cũ 400 năm (8 phút).</strong><em>&quot;Một cái cây con nặng 2kg. Năm năm sau nó nặng 80kg. 78kg kia từ đâu ra?&quot;</em> Câu trả lời phổ biến của lớp: từ đất. Giáo viên ghi lại. Rồi kể ngắn về thí nghiệm của van Helmont thế kỷ 17: trồng cây liễu trong chậu đất đã cân trước, tưới nước 5 năm, cây nặng thêm ~75kg nhưng đất chỉ nhẹ đi ~60 gram. <em>&quot;Vậy giả thuyết &#39;từ đất&#39; đúng không? 75kg đó từ đâu?&quot;</em><strong>Bước 2 — Học sinh đề xuất, rồi phải thiết kế cách kiểm tra (12 phút).</strong> Đề xuất thường gặp: từ nước · từ không khí · từ ánh sáng. <em>&quot;Ánh sáng có khối lượng không? Làm sao kiểm tra giả thuyết &#39;từ không khí&#39;?&quot;</em><strong>Bước 3 — Thí nghiệm lá bị che (20 phút, chuẩn bị từ hôm trước).</strong> Một cây đã để trong tối 48 giờ. Vài lá được dán băng đen hình chữ. Đưa ra sáng 6 giờ. Sau đó: luộc lá, ngâm cồn để tẩy diệp lục, nhỏ dung dịch iốt. Kết quả: phần lá được chiếu sáng chuyển xanh đen (có tinh bột); phần bị che thì không. <em>&quot;Kết quả này chứng minh điều gì — và KHÔNG chứng minh điều gì?&quot;</em> Câu hỏi thứ hai quan trọng hơn. Nó chứng minh ánh sáng cần cho việc tạo tinh bột. Nó <strong>không</strong> chứng minh cacbon đến từ không khí — đó là một giả thuyết khác cần bằng chứng khác. Việc phân biệt &quot;thí nghiệm này chứng minh được gì&quot; và &quot;tôi muốn nó chứng minh gì&quot; là kỹ năng khoa học cốt lõi, và nó được dạy trực tiếp ở đây. <strong>Bước 4 — Thí nghiệm thứ hai (10 phút).</strong> Cây thuỷ sinh trong ống nghiệm dưới đèn: đếm bọt khí sinh ra mỗi phút, ở các khoảng cách đèn khác nhau. Học sinh có ngay một quan hệ định lượng giữa cường độ sáng và tốc độ quang hợp. <strong>Bước 5 — Tranh luận (10 phút).</strong><em>&quot;Trồng thêm cây có giải quyết được biến đổi khí hậu không?&quot;</em> Học sinh phải dùng hiểu biết vừa xây: cây giữ cacbon trong sinh khối, nhưng khi cây chết hoặc cháy thì cacbon quay lại. Đây là câu hỏi thật sự khó, và tiêu chí chấm là chất lượng lập luận.</p><h2 id="demo-3-—-chon-loc-tu-nhien-mo-phong-bang-hat-đau-​" tabindex="-1">Demo 3 — Chọn lọc tự nhiên: mô phỏng bằng hạt đậu <a href="#demo-3-—-chon-loc-tu-nhien-mo-phong-bang-hat-đau">​</a> <a class="header-anchor" href="#demo-3-—-chon-loc-tu-nhien-mo-phong-bang-hat-đau-​" aria-label="Permalink to &quot;Demo 3 — Chọn lọc tự nhiên: mô phỏng bằng hạt đậu [​](#demo-3-—-chon-loc-tu-nhien-mo-phong-bang-hat-đau)&quot;">​</a></h2><p><strong>Lớp</strong>9–11<strong>Key concept</strong>Change<strong>Related concepts</strong>Adaptation · Patterns · Evidence<strong>Global context</strong>Orientation in space and time<strong>Statement of inquiry</strong>Những thay đổi lớn qua thời gian dài có thể sinh ra từ những khác biệt rất nhỏ được lặp đi lặp lại.<strong>Cần biết trước</strong>Sinh sản, di truyền cơ bản, biến dị</p><h3 id="dien-bien-tiet-hoc-​-2" tabindex="-1">Diễn biến tiết học <a href="#dien-bien-tiet-hoc-2">​</a> <a class="header-anchor" href="#dien-bien-tiet-hoc-​-2" aria-label="Permalink to &quot;Diễn biến tiết học [​](#dien-bien-tiet-hoc-2)&quot;">​</a></h3><p><strong>Bước 1 — Trò chơi săn mồi (20 phút).</strong> Rải lên một tấm vải hoa nhiều màu: 30 hạt đậu đỏ, 30 hạt trắng, 30 hạt nâu, 30 hạt xanh. Mỗi học sinh là một &quot;chim&quot;, có 15 giây để nhặt càng nhiều hạt càng tốt bằng một tay. Đếm số hạt còn lại theo màu. Những hạt còn lại &quot;sinh sản&quot;: mỗi hạt sống sót được nhân đôi. Chạy lại vòng hai, vòng ba, vòng bốn. <strong>Bước 2 — Nhìn vào số liệu (10 phút).</strong> Sau bốn vòng, quần thể gần như chỉ còn màu trùng với nền vải. <em>&quot;Có con hạt nào đã tự đổi màu không?&quot;</em> Đây là câu hỏi then chốt. Hiểu lầm phổ biến nhất về tiến hoá là <em>&quot;sinh vật thay đổi để thích nghi&quot;</em>. Trò chơi này phá hiểu lầm đó rất sạch: không có hạt nào đổi màu — chỉ là tỷ lệ trong quần thể đổi. <strong>Bước 3 — Chính xác hoá ngôn ngữ (10 phút).</strong> Giáo viên đưa hai câu và yêu cầu học sinh chọn câu đúng, giải thích vì sao:</p><ul><li><em>&quot;Hạt đã đổi màu để tránh bị ăn.&quot;</em></li><li><em>&quot;Những hạt vốn có màu hợp với nền sống sót nhiều hơn và để lại nhiều con hơn.&quot;</em> Cả lớp thường chọn đúng sau trò chơi — nhưng nếu hỏi trước khi chơi, đa số chọn câu đầu. <strong>Bước 4 — Đổi điều kiện (10 phút).</strong><em>&quot;Nếu ta đổi tấm vải sang màu khác giữa chừng thì sao? Nếu quần thể đã mất hết màu đó rồi?&quot;</em> Dẫn tới khái niệm đa dạng di truyền và vì sao mất đa dạng là nguy hiểm — một khái niệm trừu tượng giờ có nền cụ thể để đứng lên. <strong>Bước 5 — Nối ra thực tế (10 phút).</strong><em>&quot;Vì sao vi khuẩn kháng kháng sinh? Vì sao bác sĩ dặn phải uống hết liều?&quot;</em> Học sinh giải thích được bằng chính mô hình vừa chơi — và đây là một trong những kiến thức có ứng dụng trực tiếp nhất mà một học sinh trung học có thể mang về nhà. Ở nhà Demo 3 chơi được với gạo màu, hạt cườm, hoặc kẹo nhiều màu rải trên một cái khăn hoa. Mười lăm phút, và nó dạy chọn lọc tự nhiên tốt hơn bất kỳ chương sách nào. <a href="/ideas/inquiry-ib/ngu-van">Ngữ văn →</a></li></ul>',21)])])}const b=h(o,[["render",g]]);export{l as __pageData,b as default};
